import{_ as a,c as t,o as r,ag as s}from"./chunks/framework.Vyheyqg9.js";const h=JSON.parse('{"title":"F06 — Next.js boundaries and UI contracts","description":"","frontmatter":{},"headers":[],"relativePath":"practice/frontend/f06-next.md","filePath":"practice/frontend/f06-next.md"}'),n={name:"practice/frontend/f06-next.md"};function i(o,e,c,d,l,p){return r(),t("div",null,[...e[0]||(e[0]=[s('<h1 id="f06-—-next-js-boundaries-and-ui-contracts" tabindex="-1">F06 — Next.js boundaries and UI contracts <a class="header-anchor" href="#f06-—-next-js-boundaries-and-ui-contracts" aria-label="Permalink to “F06 — Next.js boundaries and UI contracts”">​</a></h1><p><strong>Learner status: outstanding.</strong></p><h2 id="prerequisites" tabindex="-1"><span class="hub-section-number">1 </span>Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to “1 Prerequisites”">​</a></h2><p>F05; HTTP/status/cookies plus Node server authorization and database version checks. Reuse P-328/P-330; study the three existing Next lessons.</p><h2 id="scope" tabindex="-1"><span class="hub-section-number">2 </span>Scope <a class="header-anchor" href="#scope" aria-label="Permalink to “2 Scope”">​</a></h2><p>Start with the public read-only App Router fixture, then add two-user private notes and one versioned mutation using the existing security contract. Choose cacheComponents:false or a separately justified Cache Components migration.</p><h2 id="observable-acceptance" tabindex="-1"><span class="hub-section-number">3 </span>Observable acceptance <a class="header-anchor" href="#observable-acceptance" aria-label="Permalink to “3 Observable acceptance”">​</a></h2><p>Pin framework/runtime versions; typecheck, test and production-build/start. Verify direct and client navigation, slow/loading/missing/error/retry states. Client assets/RSC contain only projected data. Authorized writes enforce owner/version server-side; foreign and stale writes fail. Public cache invalidation and private no-store behavior match the declared policy.</p><h2 id="failure-cases" tabindex="-1"><span class="hub-section-number">4 </span>Failure cases <a class="header-anchor" href="#failure-cases" aria-label="Permalink to “4 Failure cases”">​</a></h2><p>Malformed ID/JSON, missing/revoked session, forged owner, cross-origin mutation, concurrent same-version writes, deployment restart, shared-cache leakage, hydration mismatch and mutation uncertainty. Test cache counters in clean production, not only HMR.</p><h2 id="evidence-to-record" tabindex="-1"><span class="hub-section-number">5 </span>Evidence to record <a class="header-anchor" href="#evidence-to-record" aria-label="Permalink to “5 Evidence to record”">​</a></h2><p>Retain build output, HTTP/status/cache traces, safe bundle inspection, DB race results and actual browser focus/keyboard checks. Record deployment mode, durable stores, runtime secrets and rollback assumptions. No paid service/deployment is required; unrun provider/HTTPS/multi-instance tests remain explicit limitations.</p><p>Return to <a href="./">the sequence</a> and <a href="./../frontend-project.html">original P-328–P-330 specification</a>. Author verification never completes this stage.</p>',13)])])}const b=a(n,[["render",i]]);export{h as __pageData,b as default};
